#include <string>
#include <vector>
#include <unordered_map>
#include <algorithm>

class Solution {
public:
    std::vector<std::string> majorityFrequencyCharacters(std::string s) {
        std::unordered_map<char, int> freq;
        int max_f = 0;
        for (char c : s) {
            max_f = std::max(max_f, ++freq[c]);
        }
        std::vector<std::string> res;
        for (const auto& [c, f] : freq) {
            if (f == max_f) {
                res.push_back(std::string(1, c));
            }
        }
        std::sort(res.begin(), res.end());
        return res;
    }
};

import java.util.*;

class Solution {
    public String[] majorityFrequencyCharacters(String s) {
        Map<Character, Integer> freq = new HashMap<>();
        int maxF = 0;
        for (char c : s.toCharArray()) {
            int cnt = freq.getOrDefault(c, 0) + 1;
            freq.put(c, cnt);
            maxF = Math.max(maxF, cnt);
        }
        List<String> res = new ArrayList<>();
        for (Map.Entry<Character, Integer> entry : freq.entrySet()) {
            if (entry.getValue() == maxF) {
                res.add(String.valueOf(entry.getKey()));
            }
        }
        Collections.sort(res);
        return res.toArray(new String[0]);
    }
}

var majorityFrequencyCharacters = function(s) {
    const freq = new Map();
    let maxF = 0;
    for (const c of s) {
        const cnt = (freq.get(c) || 0) + 1;
        freq.set(c, cnt);
        if (cnt > maxF) maxF = cnt;
    }
    const res = [];
    for (const [c, f] of freq.entries()) {
        if (f === maxF) res.push(c);
    }
    return res.sort();
};
